grpc.protoSchema:
syntax = "proto3";
package service;

option go_package = "github.com/wundergraph/cosmo/plugin";

import "google/protobuf/wrappers.proto";

// Service definition for BffService
service BffService {
  /*
   * Lookup Courier entity by id: Work of the current courier; the entity key lets the Router resolve
   * courierChanged events (ADR 36)
   */
  rpc LookupCourierById(LookupCourierByIdRequest) returns (LookupCourierByIdResponse) {}
  /*
   * Lookup Kitchen entity by restaurantId: Active orders of one restaurant for its kitchen staff; the entity key lets the
   * Router resolve kitchenChanged events (ADR 36)
   */
  rpc LookupKitchenByRestaurantId(LookupKitchenByRestaurantIdRequest) returns (LookupKitchenByRestaurantIdResponse) {}
  /*
   * Lookup Order entity by id: Order of the current customer; the entity key lets the Router resolve
   * subscription events of the events subgraph (ADR 36)
   */
  rpc LookupOrderById(LookupOrderByIdRequest) returns (LookupOrderByIdResponse) {}
  // Accept a delivery offer addressed to the current courier
  rpc MutationAcceptDeliveryOffer(MutationAcceptDeliveryOfferRequest) returns (MutationAcceptDeliveryOfferResponse) {}
  // Apply a command to the current delivery of the courier
  rpc MutationApplyCourierDeliveryAction(MutationApplyCourierDeliveryActionRequest) returns (MutationApplyCourierDeliveryActionResponse) {}
  /*
   * Apply a kitchen command to a restaurant order; repeating START_PREPARATION or MARK_READY
   * changes nothing
   */
  rpc MutationApplyKitchenAction(MutationApplyKitchenActionRequest) returns (MutationApplyKitchenActionResponse) {}
  // Close a restaurant of the current user for new orders; repeating it changes nothing
  rpc MutationCloseRestaurant(MutationCloseRestaurantRequest) returns (MutationCloseRestaurantResponse) {}
  // Open a restaurant of the current user for new orders; repeating it changes nothing
  rpc MutationOpenRestaurant(MutationOpenRestaurantRequest) returns (MutationOpenRestaurantResponse) {}
  // Place an order for the current customer
  rpc MutationPlaceOrder(MutationPlaceOrderRequest) returns (MutationPlaceOrderResponse) {}
  // Request cancellation of an order of the current customer
  rpc MutationRequestOrderCancellation(MutationRequestOrderCancellationRequest) returns (MutationRequestOrderCancellationResponse) {}
  // Change whether the current courier receives delivery offers; AVAILABLE or UNAVAILABLE only
  rpc MutationSetCourierAvailability(MutationSetCourierAvailabilityRequest) returns (MutationSetCourierAvailabilityResponse) {}
  // Metadata for the client BFF
  rpc QueryBffInfo(QueryBffInfoRequest) returns (QueryBffInfoResponse) {}
  // Work of the current user as a courier, null if the user is not a registered courier
  rpc QueryCourier(QueryCourierRequest) returns (QueryCourierResponse) {}
  // Orders of the current customer, newest first
  rpc QueryCustomerOrders(QueryCustomerOrdersRequest) returns (QueryCustomerOrdersResponse) {}
  /*
   * Active orders of a restaurant for its kitchen; requires kitchen staff or the owner of the
   * restaurant, null if the restaurant does not exist or the user may not operate its kitchen
   */
  rpc QueryKitchen(QueryKitchenRequest) returns (QueryKitchenResponse) {}
  // Restaurants the current user owns, open and closed, ordered by identifier; menu is null
  rpc QueryMyRestaurants(QueryMyRestaurantsRequest) returns (QueryMyRestaurantsResponse) {}
  // Order of the current customer, null if it does not exist or belongs to someone else
  rpc QueryOrder(QueryOrderRequest) returns (QueryOrderResponse) {}
  // Restaurant by identifier, null if it does not exist
  rpc QueryRestaurant(QueryRestaurantRequest) returns (QueryRestaurantResponse) {}
  // Restaurants available to the customer
  rpc QueryRestaurants(QueryRestaurantsRequest) returns (QueryRestaurantsResponse) {}
}

// Key message for Order entity lookup
message LookupOrderByIdRequestKey {
  // Key field for Order entity lookup.
  string id = 1;
}

// Request message for Order entity lookup.
message LookupOrderByIdRequest {
  /*
   * List of keys to look up Order entities.
   * Order matters - each key maps to one entity in LookupOrderByIdResponse.
   */
  repeated LookupOrderByIdRequestKey keys = 1;
}

// Response message for Order entity lookup.
message LookupOrderByIdResponse {
  /*
   * List of Order entities in the same order as the keys in LookupOrderByIdRequest.
   * Always return the same number of entities as keys. Use null for entities that cannot be found.
   * 
   * Example:
   *   LookupUserByIdRequest:
   *     keys:
   *       - id: 1
   *       - id: 2
   *   LookupUserByIdResponse:
   *     result:
   *       - id: 1 # User with id 1 found
   *       - null  # User with id 2 not found
   */
  repeated Order result = 1;
}

// Key message for Kitchen entity lookup
message LookupKitchenByRestaurantIdRequestKey {
  // Key field for Kitchen entity lookup.
  string restaurant_id = 1;
}

// Request message for Kitchen entity lookup.
message LookupKitchenByRestaurantIdRequest {
  /*
   * List of keys to look up Kitchen entities.
   * Order matters - each key maps to one entity in LookupKitchenByRestaurantIdResponse.
   */
  repeated LookupKitchenByRestaurantIdRequestKey keys = 1;
}

// Response message for Kitchen entity lookup.
message LookupKitchenByRestaurantIdResponse {
  /*
   * List of Kitchen entities in the same order as the keys in LookupKitchenByRestaurantIdRequest.
   * Always return the same number of entities as keys. Use null for entities that cannot be found.
   * 
   * Example:
   *   LookupUserByIdRequest:
   *     keys:
   *       - id: 1
   *       - id: 2
   *   LookupUserByIdResponse:
   *     result:
   *       - id: 1 # User with id 1 found
   *       - null  # User with id 2 not found
   */
  repeated Kitchen result = 1;
}

// Key message for Courier entity lookup
message LookupCourierByIdRequestKey {
  // Key field for Courier entity lookup.
  string id = 1;
}

// Request message for Courier entity lookup.
message LookupCourierByIdRequest {
  /*
   * List of keys to look up Courier entities.
   * Order matters - each key maps to one entity in LookupCourierByIdResponse.
   */
  repeated LookupCourierByIdRequestKey keys = 1;
}

// Response message for Courier entity lookup.
message LookupCourierByIdResponse {
  /*
   * List of Courier entities in the same order as the keys in LookupCourierByIdRequest.
   * Always return the same number of entities as keys. Use null for entities that cannot be found.
   * 
   * Example:
   *   LookupUserByIdRequest:
   *     keys:
   *       - id: 1
   *       - id: 2
   *   LookupUserByIdResponse:
   *     result:
   *       - id: 1 # User with id 1 found
   *       - null  # User with id 2 not found
   */
  repeated Courier result = 1;
}

// Request message for bffInfo operation: Metadata for the client BFF.
message QueryBffInfoRequest {
}
// Response message for bffInfo operation: Metadata for the client BFF.
message QueryBffInfoResponse {
  // Metadata for the client BFF
  BffInfo bff_info = 1;
}
// Request message for restaurants operation: Restaurants available to the customer.
message QueryRestaurantsRequest {
  int32 first = 1;
  google.protobuf.StringValue after = 2;
}
// Response message for restaurants operation: Restaurants available to the customer.
message QueryRestaurantsResponse {
  // Restaurants available to the customer
  RestaurantConnection restaurants = 1;
}
// Request message for restaurant operation: Restaurant by identifier, null if it does not exist.
message QueryRestaurantRequest {
  string id = 1;
}
// Response message for restaurant operation: Restaurant by identifier, null if it does not exist.
message QueryRestaurantResponse {
  // Restaurant by identifier, null if it does not exist
  Restaurant restaurant = 1;
}
// Request message for order operation: Order of the current customer, null if it does not exist or belongs to someone else.
message QueryOrderRequest {
  string id = 1;
}
// Response message for order operation: Order of the current customer, null if it does not exist or belongs to someone else.
message QueryOrderResponse {
  // Order of the current customer, null if it does not exist or belongs to someone else
  Order order = 1;
}
// Request message for customerOrders operation: Orders of the current customer, newest first.
message QueryCustomerOrdersRequest {
  int32 first = 1;
  google.protobuf.StringValue after = 2;
}
// Response message for customerOrders operation: Orders of the current customer, newest first.
message QueryCustomerOrdersResponse {
  // Orders of the current customer, newest first
  OrderConnection customer_orders = 1;
}
// Request message for myRestaurants operation: Restaurants the current user owns, open and closed, ordered by identifier; menu is null.
message QueryMyRestaurantsRequest {
  int32 first = 1;
  google.protobuf.StringValue after = 2;
}
// Response message for myRestaurants operation: Restaurants the current user owns, open and closed, ordered by identifier; menu is null.
message QueryMyRestaurantsResponse {
  // Restaurants the current user owns, open and closed, ordered by identifier; menu is null
  RestaurantConnection my_restaurants = 1;
}
/*
 * Request message for kitchen operation: Active orders of a restaurant for its kitchen; requires kitchen staff or the owner of the
 * restaurant, null if the restaurant does not exist or the user may not operate its kitchen.
 */
message QueryKitchenRequest {
  string restaurant_id = 1;
}
/*
 * Response message for kitchen operation: Active orders of a restaurant for its kitchen; requires kitchen staff or the owner of the
 * restaurant, null if the restaurant does not exist or the user may not operate its kitchen.
 */
message QueryKitchenResponse {
  /*
   * Active orders of a restaurant for its kitchen; requires kitchen staff or the owner of the
   * restaurant, null if the restaurant does not exist or the user may not operate its kitchen
   */
  Kitchen kitchen = 1;
}
// Request message for courier operation: Work of the current user as a courier, null if the user is not a registered courier.
message QueryCourierRequest {
}
// Response message for courier operation: Work of the current user as a courier, null if the user is not a registered courier.
message QueryCourierResponse {
  // Work of the current user as a courier, null if the user is not a registered courier
  Courier courier = 1;
}
// Request message for placeOrder operation: Place an order for the current customer.
message MutationPlaceOrderRequest {
  PlaceOrderInput input = 1;
}
// Response message for placeOrder operation: Place an order for the current customer.
message MutationPlaceOrderResponse {
  // Place an order for the current customer
  PlaceOrderPayload place_order = 1;
}
// Request message for requestOrderCancellation operation: Request cancellation of an order of the current customer.
message MutationRequestOrderCancellationRequest {
  RequestOrderCancellationInput input = 1;
}
// Response message for requestOrderCancellation operation: Request cancellation of an order of the current customer.
message MutationRequestOrderCancellationResponse {
  // Request cancellation of an order of the current customer
  RequestOrderCancellationPayload request_order_cancellation = 1;
}
// Request message for openRestaurant operation: Open a restaurant of the current user for new orders; repeating it changes nothing.
message MutationOpenRestaurantRequest {
  string restaurant_id = 1;
}
// Response message for openRestaurant operation: Open a restaurant of the current user for new orders; repeating it changes nothing.
message MutationOpenRestaurantResponse {
  // Open a restaurant of the current user for new orders; repeating it changes nothing
  RestaurantOpeningPayload open_restaurant = 1;
}
// Request message for closeRestaurant operation: Close a restaurant of the current user for new orders; repeating it changes nothing.
message MutationCloseRestaurantRequest {
  string restaurant_id = 1;
}
// Response message for closeRestaurant operation: Close a restaurant of the current user for new orders; repeating it changes nothing.
message MutationCloseRestaurantResponse {
  // Close a restaurant of the current user for new orders; repeating it changes nothing
  RestaurantOpeningPayload close_restaurant = 1;
}
/*
 * Request message for applyKitchenAction operation: Apply a kitchen command to a restaurant order; repeating START_PREPARATION or MARK_READY
 * changes nothing.
 */
message MutationApplyKitchenActionRequest {
  KitchenActionInput input = 1;
}
/*
 * Response message for applyKitchenAction operation: Apply a kitchen command to a restaurant order; repeating START_PREPARATION or MARK_READY
 * changes nothing.
 */
message MutationApplyKitchenActionResponse {
  /*
   * Apply a kitchen command to a restaurant order; repeating START_PREPARATION or MARK_READY
   * changes nothing
   */
  KitchenActionPayload apply_kitchen_action = 1;
}
// Request message for setCourierAvailability operation: Change whether the current courier receives delivery offers; AVAILABLE or UNAVAILABLE only.
message MutationSetCourierAvailabilityRequest {
  CourierAvailability availability = 1;
}
// Response message for setCourierAvailability operation: Change whether the current courier receives delivery offers; AVAILABLE or UNAVAILABLE only.
message MutationSetCourierAvailabilityResponse {
  // Change whether the current courier receives delivery offers; AVAILABLE or UNAVAILABLE only
  CourierPayload set_courier_availability = 1;
}
// Request message for acceptDeliveryOffer operation: Accept a delivery offer addressed to the current courier.
message MutationAcceptDeliveryOfferRequest {
  string offer_id = 1;
}
// Response message for acceptDeliveryOffer operation: Accept a delivery offer addressed to the current courier.
message MutationAcceptDeliveryOfferResponse {
  // Accept a delivery offer addressed to the current courier
  CourierPayload accept_delivery_offer = 1;
}
// Request message for applyCourierDeliveryAction operation: Apply a command to the current delivery of the courier.
message MutationApplyCourierDeliveryActionRequest {
  string delivery_id = 1;
  CourierDeliveryAction action = 2;
}
// Response message for applyCourierDeliveryAction operation: Apply a command to the current delivery of the courier.
message MutationApplyCourierDeliveryActionResponse {
  // Apply a command to the current delivery of the courier
  CourierPayload apply_courier_delivery_action = 1;
}

/*
 * Order of the current customer; the entity key lets the Router resolve
 * subscription events of the events subgraph (ADR 36)
 */
message Order {
  reserved 7;
  // Order identifier
  string id = 1;
  // Customer-facing lifecycle status
  OrderStatus status = 2;
  // Why the order ended, set only for CANCELLED and FAILED
  OrderEndReason end_reason = 3;
  // Restaurant that fulfills the order
  Restaurant restaurant = 4;
  // Ordered items
  repeated OrderItem items = 5;
  // Total amount of the order
  Money total = 6;
  // Moment the order was placed in RFC 3339
  string placed_at = 8;
  // Milestones in chronological order
  repeated OrderMilestone milestones = 9;
  // Cancellation availability, null when cancellation is not possible now
  OrderCancellationAvailability cancellation = 10;
}

/*
 * Active orders of one restaurant for its kitchen staff; the entity key lets the
 * Router resolve kitchenChanged events (ADR 36)
 */
message Kitchen {
  // Restaurant the kitchen belongs to; menu is null
  Restaurant restaurant = 1;
  /*
   * Orders in RECEIVED, QUEUED, PREPARING, ASSEMBLED and READY: RECEIVED by ascending
   * receivedAt, then the kitchen queue order, then the rest by ascending receivedAt
   */
  repeated KitchenOrder orders = 2;
  // Identifier of the restaurant the kitchen belongs to
  string restaurant_id = 3;
}

/*
 * Work of the current courier; the entity key lets the Router resolve
 * courierChanged events (ADR 36)
 */
message Courier {
  // Current availability
  CourierAvailability availability = 1;
  // Pending delivery offers, empty unless AVAILABLE
  repeated DeliveryOffer offers = 2;
  // Delivery in progress, null if none
  CourierDelivery current_delivery = 3;
  // Courier identifier, the subject of the current user
  string id = 4;
}

message BffInfo {
  // Service name
  string name = 1;
  // Service version
  string version = 2;
}

message RestaurantConnection {
  // Restaurants of the page
  repeated RestaurantEdge edges = 1;
  // Pagination state
  PageInfo page_info = 2;
}

// Restaurant as shown to a customer
message Restaurant {
  // Restaurant identifier
  string id = 1;
  // Display name
  string name = 2;
  // Human-readable address
  string address = 3;
  // Whether the restaurant accepts new orders now
  bool accepting_orders = 4;
  // Current menu, null if the restaurant has not published one
  Menu menu = 5;
}

message OrderConnection {
  // Orders of the page, newest first
  repeated OrderEdge edges = 1;
  // Pagination state
  PageInfo page_info = 2;
}

message PlaceOrderInput {
  reserved 3;
  // Restaurant to order from
  string restaurant_id = 1;
  // Ordered items
  repeated OrderLineInput items = 2;
  // Client-generated key of this checkout attempt, reused on manual retry
  string idempotency_key = 4;
}

message PlaceOrderPayload {
  // Placed order, null if problems is not empty
  Order order = 1;
  // Business problems that prevented placing the order
  repeated PlaceOrderProblem problems = 2;
}

message RequestOrderCancellationInput {
  // Order to cancel
  string order_id = 1;
  // Client-generated key of this cancellation attempt, reused on manual retry
  string request_id = 2;
  // Optional free-text reason given by the customer
  google.protobuf.StringValue reason = 3;
}

message RequestOrderCancellationPayload {
  // Outcome, null if problem is set
  OrderCancellationOutcome outcome = 1;
  // Business problem, null if outcome is set
  OrderCancellationProblem problem = 2;
}

// Result of opening or closing a restaurant by its owner
message RestaurantOpeningPayload {
  // Restaurant after the command; acceptingOrders is its opening state, menu is null
  Restaurant restaurant = 1;
  // False when the restaurant was already in the requested state
  bool changed = 2;
}

message KitchenActionInput {
  // Restaurant of the order
  string restaurant_id = 1;
  // Restaurant order identifier (KitchenOrder.id)
  string kitchen_order_id = 2;
  // Command to apply
  KitchenAction action = 3;
}

message KitchenActionPayload {
  // Order after the command; null if problem is set or the order left the kitchen
  KitchenOrder order = 1;
  // Business problem, null on success
  KitchenActionProblemCode problem = 2;
}

message CourierPayload {
  // Courier after the command
  Courier courier = 1;
  // Business problem, null on success
  CourierProblemCode problem = 2;
}

// Exact monetary amount
message Money {
  // Decimal string with a dot separator, for example "12.50"
  string amount = 1;
  // ISO 4217 currency code
  string currency = 2;
}

// Cursor pagination state of a connection
message PageInfo {
  // Whether more items follow endCursor
  bool has_next_page = 1;
  // Cursor of the last returned item, null for an empty page
  google.protobuf.StringValue end_cursor = 2;
}

// Menu of one restaurant
message Menu {
  // Menu items in display order
  repeated MenuItem items = 1;
}

// Item of a restaurant menu
message MenuItem {
  // Menu item identifier
  string id = 1;
  // Display name
  string name = 2;
  // Short description, null if absent
  google.protobuf.StringValue description = 3;
  // Current price of one unit
  Money price = 4;
  // Whether the item can be ordered now
  bool available = 5;
}

message RestaurantEdge {
  // Opaque cursor of this item
  string cursor = 1;
  // Restaurant
  Restaurant node = 2;
}

// Customer-facing lifecycle of an order
enum OrderStatus {
  ORDER_STATUS_UNSPECIFIED = 0;
  // Order is placed and waits for confirmation
  ORDER_STATUS_RECEIVED = 1;
  // Order is confirmed and waits for the kitchen
  ORDER_STATUS_CONFIRMED = 2;
  // Kitchen is preparing the order
  ORDER_STATUS_PREPARING = 3;
  // Order is ready and waits for the courier
  ORDER_STATUS_READY_FOR_PICKUP = 4;
  // Courier picked the order up and is on the way
  ORDER_STATUS_PICKED_UP = 5;
  // Order is delivered
  ORDER_STATUS_DELIVERED = 6;
  // Order is cancelled before fulfillment
  ORDER_STATUS_CANCELLED = 7;
  // Order could not be fulfilled
  ORDER_STATUS_FAILED = 8;
}

// Why an order ended without delivery
enum OrderEndReason {
  ORDER_END_REASON_UNSPECIFIED = 0;
  // Customer cancelled the order
  ORDER_END_REASON_CUSTOMER_CANCELLED = 1;
  // Restaurant could not accept the order
  ORDER_END_REASON_RESTAURANT_REJECTED = 2;
  // Delivery did not succeed
  ORDER_END_REASON_DELIVERY_FAILED = 3;
  // Order was not fulfilled for another reason
  ORDER_END_REASON_NOT_FULFILLED = 4;
}

// Notable moment in the progress of an order
enum OrderMilestoneKind {
  ORDER_MILESTONE_KIND_UNSPECIFIED = 0;
  // Order is placed
  ORDER_MILESTONE_KIND_PLACED = 1;
  // Order is confirmed
  ORDER_MILESTONE_KIND_CONFIRMED = 2;
  // Kitchen started preparation
  ORDER_MILESTONE_KIND_PREPARATION_STARTED = 3;
  // Order is ready for pickup
  ORDER_MILESTONE_KIND_READY_FOR_PICKUP = 4;
  // Courier is assigned to the order
  ORDER_MILESTONE_KIND_COURIER_ASSIGNED = 5;
  // Courier picked the order up
  ORDER_MILESTONE_KIND_PICKED_UP = 6;
  // Order is delivered
  ORDER_MILESTONE_KIND_DELIVERED = 7;
  // Order ended without delivery
  ORDER_MILESTONE_KIND_ENDED = 8;
}

message OrderMilestone {
  // Kind of the milestone
  OrderMilestoneKind kind = 1;
  // Moment of the milestone in RFC 3339
  string occurred_at = 2;
}

// Menu item as recorded in an order
message OrderedMenuItem {
  // Menu item identifier
  string id = 1;
  // Display name
  string name = 2;
}

message OrderItem {
  // Ordered menu item
  OrderedMenuItem menu_item = 1;
  // Number of units
  int32 quantity = 2;
  // Price of one unit at the time of ordering
  Money unit_price = 3;
  // Price of all units of this line
  Money line_total = 4;
}

// Present only while the customer may request cancellation
message OrderCancellationAvailability {
  // Moment in RFC 3339 after which cancellation is no longer possible
  string available_until = 1;
}

message OrderEdge {
  // Opaque cursor of this item
  string cursor = 1;
  // Order
  Order node = 2;
}

// Stage of a restaurant order in the kitchen
enum KitchenOrderStage {
  KITCHEN_ORDER_STAGE_UNSPECIFIED = 0;
  // Order arrived and waits for the kitchen to accept or reject it
  KITCHEN_ORDER_STAGE_RECEIVED = 1;
  // Order is accepted and waits in the kitchen queue
  KITCHEN_ORDER_STAGE_QUEUED = 2;
  // Kitchen is preparing the order
  KITCHEN_ORDER_STAGE_PREPARING = 3;
  // Order is assembled and waits to be marked ready
  KITCHEN_ORDER_STAGE_ASSEMBLED = 4;
  // Order is ready for pickup
  KITCHEN_ORDER_STAGE_READY = 5;
}

// Line of a restaurant order as the kitchen sees it
message KitchenOrderItem {
  // Display name of the menu item, empty if it is no longer in the menu
  string name = 1;
  // Number of units
  int32 quantity = 2;
}

// Order of a restaurant as its kitchen sees it
message KitchenOrder {
  // Restaurant order identifier, used by the kitchen commands
  string id = 1;
  // Customer order identifier
  string order_id = 2;
  // Current stage in the kitchen
  KitchenOrderStage stage = 3;
  // Ordered items
  repeated KitchenOrderItem items = 4;
  // Moment the restaurant received the order in RFC 3339
  string received_at = 5;
}

// Command of the kitchen over one restaurant order
enum KitchenAction {
  KITCHEN_ACTION_UNSPECIFIED = 0;
  // Accept a RECEIVED order into the kitchen queue
  KITCHEN_ACTION_ACCEPT = 1;
  // Reject a RECEIVED order
  KITCHEN_ACTION_REJECT = 2;
  // Start preparing a QUEUED order
  KITCHEN_ACTION_START_PREPARATION = 3;
  // Mark a PREPARING order assembled
  KITCHEN_ACTION_MARK_ASSEMBLED = 4;
  // Mark an ASSEMBLED order ready for pickup
  KITCHEN_ACTION_MARK_READY = 5;
}

// Business reason why a kitchen command cannot be applied
enum KitchenActionProblemCode {
  KITCHEN_ACTION_PROBLEM_CODE_UNSPECIFIED = 0;
  // The order is not in a stage that allows this command
  KITCHEN_ACTION_PROBLEM_CODE_ORDER_STAGE_CONFLICT = 1;
}

// Availability of a courier for new deliveries
enum CourierAvailability {
  COURIER_AVAILABILITY_UNSPECIFIED = 0;
  // Courier receives delivery offers
  COURIER_AVAILABILITY_AVAILABLE = 1;
  // Courier is on a delivery
  COURIER_AVAILABILITY_BUSY = 2;
  // Courier does not receive delivery offers
  COURIER_AVAILABILITY_UNAVAILABLE = 3;
}

// Delivery offered to the courier, valid until expiresAt
message DeliveryOffer {
  reserved 4;
  // Offer identifier
  string id = 1;
  // Delivery the offer is for
  string delivery_id = 2;
  // Where to pick the order up
  string pickup_address = 3;
  // Moment in RFC 3339 after which the offer cannot be accepted
  string expires_at = 5;
  // Customer order the delivery is for
  string order_id = 6;
}

// Stage of a delivery assigned to the courier
enum CourierDeliveryStage {
  COURIER_DELIVERY_STAGE_UNSPECIFIED = 0;
  // Courier is going to the restaurant
  COURIER_DELIVERY_STAGE_ASSIGNED = 1;
  // Courier has the order and is going to the customer
  COURIER_DELIVERY_STAGE_PICKED_UP = 2;
}

// Delivery the courier is currently carrying out
message CourierDelivery {
  reserved 5;
  // Delivery identifier
  string id = 1;
  // Customer order identifier
  string order_id = 2;
  // Current stage
  CourierDeliveryStage stage = 3;
  // Where to pick the order up
  string pickup_address = 4;
}

// Command of the courier over the current delivery
enum CourierDeliveryAction {
  COURIER_DELIVERY_ACTION_UNSPECIFIED = 0;
  // Confirm the order is picked up at the restaurant
  COURIER_DELIVERY_ACTION_CONFIRM_PICKUP = 1;
  // Confirm the order is handed to the customer
  COURIER_DELIVERY_ACTION_CONFIRM_DELIVERY = 2;
}

// Business reason why a courier command cannot be applied
enum CourierProblemCode {
  COURIER_PROBLEM_CODE_UNSPECIFIED = 0;
  // The offer expired or was taken
  COURIER_PROBLEM_CODE_OFFER_NOT_AVAILABLE = 1;
  // The delivery is not in a stage that allows this command
  COURIER_PROBLEM_CODE_DELIVERY_STAGE_CONFLICT = 2;
}

message OrderLineInput {
  // Menu item identifier
  string menu_item_id = 1;
  // Number of units, at least 1
  int32 quantity = 2;
}

// Business reason why an order cannot be placed
enum PlaceOrderProblemCode {
  PLACE_ORDER_PROBLEM_CODE_UNSPECIFIED = 0;
  // One or more items cannot be ordered now
  PLACE_ORDER_PROBLEM_CODE_ORDER_ITEM_UNAVAILABLE = 1;
  // Order total is below the restaurant minimum
  PLACE_ORDER_PROBLEM_CODE_ORDER_TOTAL_BELOW_MINIMUM = 2;
  // Order total is above the allowed maximum
  PLACE_ORDER_PROBLEM_CODE_ORDER_TOTAL_ABOVE_MAXIMUM = 3;
  // Restaurant does not accept orders now
  PLACE_ORDER_PROBLEM_CODE_RESTAURANT_NOT_ACCEPTING_ORDERS = 4;
}

message PlaceOrderProblem {
  // Reason code
  PlaceOrderProblemCode code = 1;
  // Menu items the problem refers to, empty if it refers to the whole order
  repeated string menu_item_ids = 2;
}

// Accepted result of a cancellation request
enum OrderCancellationOutcome {
  ORDER_CANCELLATION_OUTCOME_UNSPECIFIED = 0;
  // Request is accepted and the order will be cancelled asynchronously
  ORDER_CANCELLATION_OUTCOME_REQUESTED = 1;
  // Order was already cancelled
  ORDER_CANCELLATION_OUTCOME_ALREADY_CANCELLED = 2;
}

// Business reason why cancellation cannot be requested
enum OrderCancellationProblemCode {
  ORDER_CANCELLATION_PROBLEM_CODE_UNSPECIFIED = 0;
  // Cancellation window has not opened yet
  ORDER_CANCELLATION_PROBLEM_CODE_CANCELLATION_WINDOW_NOT_OPEN = 1;
  // Cancellation window has closed
  ORDER_CANCELLATION_PROBLEM_CODE_CANCELLATION_WINDOW_EXPIRED = 2;
  // Order is already delivered or failed
  ORDER_CANCELLATION_PROBLEM_CODE_ORDER_ALREADY_FINAL = 3;
}

message OrderCancellationProblem {
  // Reason code
  OrderCancellationProblemCode code = 1;
}
